                          <div class="reply-actions">
                            <button class="cancel-btn" @click="closeReplyInput">取消</button>
                            <button class="send-btn" :disabled="!replyContent.trim() || submitting" @click="submitReply">发布</button>
                          </div>
                        </div>
                        <div v-if="replyImgPath" class="img-preview small"><img :src="replyImgPath" @click="openImagePreview(replyImgPath)" /><span class="remove-btn" @click="replyImgPath = ''">×</span></div>
                      </div>
                    </div>
                    <!-- 回复列表 -->
                    <div v-if="comment.replyCount > 0" class="reply-section">
                      <div v-if="!comment.showReplies" class="view-replies" @click="loadReplies(comment)">共{{ comment.replyCount }}条回复，点击查看<svg viewBox="0 0 24 24" width="14" height="14"><path fill="currentColor" d="M7.41 8.59L12 13.17l4.59-4.58L18 10l-6 6-6-6 1.41-1.41z"/></svg></div>
                      <template v-else>
                        <div v-for="reply in comment.replies" :key="reply.commentId" class="reply-item" :data-comment-id="reply.commentId">
                          <img :src="avatarUrl(reply.userAvatar, reply.userNickName)" alt="" class="reply-avatar clickable" @click="goToUserSpace(reply.userId)" @error="onAvatarError($event, reply.userNickName)" />
                          <div class="reply-body">
                            <div class="reply-user-info">
                              <span class="username clickable" @click="goToUserSpace(reply.userId)">{{ reply.userNickName }}</span>
                              <span v-if="reply.userId === articleAuthorId" class="up-tag">UP</span>
                              <template v-if="reply.replyUserId"><span class="reply-arrow">回复</span><span class="username clickable" @click="goToUserSpace(reply.replyUserId)">@{{ reply.replyNickName }}</span></template>
                              <span class="colon">：</span>
                            </div>
                            <span class="reply-text">{{ reply.content }}</span>
                            <div v-if="reply.imgPath" class="reply-image" @click="openImagePreview(reply.imgPath)"><img :src="reply.imgPath" /></div>
                            <div class="reply-meta">
                              <span class="time">{{ formatTime(reply.createTime) }}</span>
