        </div>

        <!-- 加载更多评论 -->
        <div v-if="hasMore" class="load-more-comments" @click="loadMoreComments">
          {{ loadingMore ? '加载中...' : '查看更多评论' }}
        </div>
      </template>
    </div>

    <!-- 图片预览弹窗 -->
    <div v-if="previewImage" class="image-preview-modal" @click="previewImage = ''">
      <img :src="previewImage" @click.stop />
      <span class="close-btn" @click="previewImage = ''">×</span>
    </div>
    </div>

    <!-- 移动端图片预览弹窗（单独放在外层） -->
    <div v-if="isMobile && previewImage" class="image-preview-modal" @click="previewImage = ''">
      <img :src="previewImage" @click.stop />
      <span class="close-btn" @click="previewImage = ''">×</span>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, nextTick, watch, onMounted, onUnmounted } from 'vue'
import request from '../utils/request'
import { uploadFile } from '../utils/upload'
import { avatarUrl, onAvatarError } from '../utils/avatar'

const props = defineProps<{
  articleId: string
  articleAuthorId: string
  targetCommentId?: string  // URL中的评论ID，用于定位滚动
}>()

// 移动端检测
const isMobile = ref(false)
const showMobilePanel = ref(false)
const panelContentRef = ref<HTMLElement | null>(null)

function checkMobile() {
  isMobile.value = window.innerWidth <= 768
}

function openMobilePanel() {
  showMobilePanel.value = true
  document.body.style.overflow = 'hidden' // 禁止背景滚动
  if (comments.value.length === 0) {
    fetchComments()
  }
}

function closeMobilePanel() {
  showMobilePanel.value = false
  document.body.style.overflow = '' // 恢复滚动
}

function formatCount(count: number): string {
  if (count >= 10000) {
    return (count / 10000).toFixed(1) + '万'
  } else if (count >= 1000) {
    return (count / 1000).toFixed(1) + 'k'
  }
  return count.toString()
}

onMounted(() => {
  checkMobile()
  window.addEventListener('resize', checkMobile)
  // PC端自动加载评论
  if (!isMobile.value) {
    fetchComments()
  }
})

onUnmounted(() => {
  window.removeEventListener('resize', checkMobile)
  document.body.style.overflow = ''
})

// 评论数据
const comments = ref<any[]>([])
const totalCount = ref(0)
const loading = ref(false)
const loadingMore = ref(false)
const hasMore = ref(false)
const page = ref(1)
const pageSize = 10
const sortType = ref<'hot' | 'new'>('hot')

// 顶部输入框
const topCommentContent = ref('')
const topInputFocused = ref(false)
const topImgPath = ref('')
const topImgUploading = ref(false)
const topImgProgress = ref(0)
const submitting = ref(false)

// 回复输入框
const activeReplyId = ref<string | null>(null)
const activeReplyTarget = ref<any>(null)  // 被回复的目标
const activeRootComment = ref<any>(null)  // 所属顶级评论
const replyContent = ref('')
const replyImgPath = ref('')
const replyImgUploading = ref(false)
const replyImgProgress = ref(0)

// 图片预览
const previewImage = ref('')

// 用户信息
const myAvatar = ref(localStorage.getItem('avatar') || '')
const myNickName = ref(localStorage.getItem('nickName') || '')
const myUserId = ref(localStorage.getItem('userId') || '')

// 判断是否是自己的评论
function isMyComment(comment: any): boolean {
  return myUserId.value && comment.userId === myUserId.value
}

// 获取评论列表
async function fetchComments(isLoadMore = false) {
  if (!isLoadMore) {
    loading.value = true
    page.value = 1
  } else {
    loadingMore.value = true
  }

  try {
    const res = await request.get('/comment/list', {
      params: {
        articleId: props.articleId,
        page: page.value,
        size: pageSize,
        sort: sortType.value
      }
    })
    if (res.code === 200) {
      const data = res.data
      if (isLoadMore) {
        comments.value.push(...data.records)
      } else {
        comments.value = data.records
      }
      totalCount.value = data.total
      hasMore.value = data.current < data.pages
      
      // 如果有目标评论ID，加载完成后滚动定位
      if (!isLoadMore && props.targetCommentId) {
        await nextTick()
        scrollToTargetComment()
      }
    }
  } finally {
    loading.value = false
    loadingMore.value = false
  }
}

// 滚动到目标评论
async function scrollToTargetComment() {
  if (!props.targetCommentId) return
  
  // 等待DOM更新
  await nextTick()
  
  // 查找目标评论元素
  const targetElement = document.querySelector(`[data-comment-id="${props.targetCommentId}"]`)
  
  if (targetElement) {
    // 滚动到目标位置
    targetElement.scrollIntoView({ behavior: 'smooth', block: 'center' })
    
    // 添加高亮效果
    targetElement.classList.add('comment-highlight')
    
    // 3秒后移除高亮
    setTimeout(() => {
      targetElement.classList.remove('comment-highlight')
    }, 3000)
  } else {
    // 可能是回复，需要在评论列表中找到对应的顶级评论并展开
    await findAndExpandTargetComment()
  }
}

// 查找并展开目标评论（可能是回复）
async function findAndExpandTargetComment() {
  if (!props.targetCommentId) return
  
  // 遍历所有顶级评论，检查是否需要展开回复列表
  for (const comment of comments.value) {
    // 如果目标就是顶级评论，直接滚动
    if (comment.commentId === props.targetCommentId) {
      await nextTick()
      const el = document.querySelector(`[data-comment-id="${props.targetCommentId}"]`)
      if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' })
        el.classList.add('comment-highlight')
        setTimeout(() => el.classList.remove('comment-highlight'), 3000)
      }
      return
    }
    
    // 如果有回复，尝试加载回复列表
    if (comment.replyCount > 0 && !comment.showReplies) {
      // 展开回复列表
      await loadReplies(comment)
      await nextTick()
      
      // 检查目标是否在回复列表中
      const targetReply = comment.replies?.find((r: any) => r.commentId === props.targetCommentId)
      if (targetReply) {
        await nextTick()
        const el = document.querySelector(`[data-comment-id="${props.targetCommentId}"]`)
        if (el) {
          el.scrollIntoView({ behavior: 'smooth', block: 'center' })
          el.classList.add('comment-highlight')
          setTimeout(() => el.classList.remove('comment-highlight'), 3000)
        }
        return
      } else {
        // 没找到，收起回复
        comment.showReplies = false
      }
    }
  }
}

function loadMoreComments() {
  if (loadingMore.value) return
  page.value++
  fetchComments(true)
}

function changeSortType(type: 'hot' | 'new') {
  if (sortType.value === type) return
  sortType.value = type
  fetchComments()
}

// 发布顶级评论
async function submitTopComment() {
  if (!topCommentContent.value.trim() || submitting.value) return
  if (!checkLogin()) return

  submitting.value = true
  try {
    const res = await request.post('/comment/create', {
      articleId: props.articleId,
      articleUserId: props.articleAuthorId,
      content: topCommentContent.value.trim(),
      imgPath: topImgPath.value || null
    })
    if (res.code === 200) {
      topCommentContent.value = ''
      topImgPath.value = ''
      topInputFocused.value = false
      fetchComments()
    }
  } finally {
    submitting.value = false
  }
}

// 打开回复输入框
function openReplyInput(target: any, root: any) {
  if (!checkLogin()) return
  
  activeReplyId.value = target.commentId
  activeReplyTarget.value = target.commentId === root.commentId ? null : target
  activeRootComment.value = root
  replyContent.value = ''
  replyImgPath.value = ''
  
  nextTick(() => {
    const textarea = document.querySelector('.inline-reply-box .reply-textarea') as HTMLTextAreaElement
    textarea?.focus()
  })
}

function closeReplyInput() {
  activeReplyId.value = null
  activeReplyTarget.value = null
  activeRootComment.value = null
  replyContent.value = ''
  replyImgPath.value = ''
}

// 发布回复
async function submitReply() {
  if (!replyContent.value.trim() || submitting.value) return
  if (!activeRootComment.value) return

  // 先保存引用，因为 closeReplyInput 会清空
  const rootComment = activeRootComment.value

  submitting.value = true
  try {
    const data: any = {
      articleId: props.articleId,
      articleUserId: props.articleAuthorId,
      content: replyContent.value.trim(),
      imgPath: replyImgPath.value || null,
      parentId: rootComment.commentId
    }
    
    // 回复二级评论时设置 replyUserId
    if (activeReplyTarget.value) {
      data.replyUserId = activeReplyTarget.value.userId
    }

    const res = await request.post('/comment/create', data)
    if (res.code === 200) {
      closeReplyInput()
      // 刷新该评论的回复列表
      await loadReplies(rootComment)
      // 更新回复数
      rootComment.replyCount = (rootComment.replyCount || 0) + 1
    }
  } finally {
    submitting.value = false
  }
}

// 加载回复
async function loadReplies(comment: any) {
  try {
    const res = await request.get('/comment/replies', {
      params: { commentId: comment.commentId, page: 1, size: 5 }
    })
    if (res.code === 200) {
      comment.replies = res.data.records
      comment.showReplies = true
      comment.hasMoreReplies = res.data.hasMore
      comment.replyPage = 1
    }
  } catch (e) {
    console.error('加载回复失败', e)
  }
}

async function loadMoreReplies(comment: any) {
  comment.replyPage = (comment.replyPage || 1) + 1
  try {
    const res = await request.get('/comment/replies', {
      params: { commentId: comment.commentId, page: comment.replyPage, size: 5 }
    })
    if (res.code === 200) {
      comment.replies.push(...res.data.records)
      comment.hasMoreReplies = res.data.hasMore
    }
  } catch (e) {
    console.error('加载更多回复失败', e)
  }
}

// 点赞/点踩
async function toggleLike(item: any) {
  if (!checkLogin()) return
  try {
    const res = await request.post(`/comment/${item.commentId}/action`, {
      actionType: 0,  // 0-点赞 1-点踩
      articleId: props.articleId,
      articleUserId: props.articleAuthorId
    })
    if (res.code === 200) {
      item.hasLiked = res.data.hasLiked
      item.hasDisliked = false  // 点赞时取消点踩
      item.likeCount = res.data.likeCount
    }
  } catch (e) {
    console.error('点赞失败', e)
  }
}

async function toggleDislike(item: any) {
  if (!checkLogin()) return
  try {
    const res = await request.post(`/comment/${item.commentId}/action`, {
      actionType: 1,  // 0-点赞 1-点踩
      articleId: props.articleId,
      articleUserId: props.articleAuthorId
    })
    if (res.code === 200) {
      item.hasDisliked = res.data.hasDisliked
      item.hasLiked = false  // 点踩时取消点赞
      item.likeCount = res.data.likeCount  // 更新点赞数（可能从点赞变点踩，需要-1）
    }
  } catch (e) {
    console.error('点踩失败', e)
  }
}

// 删除评论
async function deleteComment(comment: any, isReply: boolean = false, rootComment?: any) {
  if (!confirm('确定要删除这条评论吗？')) return
  
  try {
    const res = await request.delete(`/comment/${comment.commentId}`)
    if (res.code === 200) {
      if (isReply && rootComment) {
        // 删除的是回复，刷新回复列表
        await loadReplies(rootComment)
        rootComment.replyCount = Math.max(0, (rootComment.replyCount || 0) - 1)
      } else {
        // 删除的是顶级评论，刷新评论列表
        await fetchComments()
      }
    }
  } catch (e: any) {
    alert(e.message || '删除失败')
  }
}

// 分享评论
async function shareComment(comment: any) {
  if (!checkLogin()) return
  
  // 构建评论链接
  const url = `${window.location.origin}/article/${props.articleId}?commentId=${comment.commentId}`
  
  try {
    // 复制链接到剪贴板
    await navigator.clipboard.writeText(url)
    
    // 调用后端接口记录分享
    await request.post('/share/record', {
      articleId: props.articleId,
      articleUserId: props.articleAuthorId,
      commentId: comment.commentId,
      shareType: 0
    })
    
    // 显示成功提示
    showShareToast('评论链接已复制')
  } catch (error) {
    // 备用方案
    const input = document.createElement('input')
    input.value = url
    document.body.appendChild(input)
    input.select()
    document.execCommand('copy')
    document.body.removeChild(input)
    showShareToast('评论链接已复制')
  }
}

// 显示分享提示
function showShareToast(message: string) {
  const toast = document.createElement('div')
  toast.className = 'share-toast'
  toast.innerHTML = `
    <svg viewBox="0 0 24 24" width="18" height="18" style="fill: var(--ej-accent)">
      <path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41L9 16.17z"/>
    </svg>
    <span>${message}</span>
  `
  document.body.appendChild(toast)
  
  setTimeout(() => {
    toast.classList.add('fade-out')
    setTimeout(() => {
      document.body.removeChild(toast)
    }, 300)
  }, 2000)
}

// 图片上传
async function handleImageSelect(event: Event, type: 'top' | 'reply') {
  const input = event.target as HTMLInputElement
  const file = input.files?.[0]
  if (!file) return
  if (file.size > 5 * 1024 * 1024) {
    alert('图片不能超过5MB')
    input.value = ''
    return
  }

  if (type === 'top') {
    topImgUploading.value = true
    topImgProgress.value = 0
  } else {
    replyImgUploading.value = true
    replyImgProgress.value = 0
  }

  try {
    const res = await uploadFile({
      url: '/file/upload-comment-image',
      file,
      onProgress: (percent) => {
        if (type === 'top') {
          topImgProgress.value = percent
        } else {
          replyImgProgress.value = percent
        }
      }
    })
    if (res.code === 200) {
      if (type === 'top') {
        topImgPath.value = res.data!.url
      } else {
        replyImgPath.value = res.data!.url
      }
    }
  } catch (e: any) {
    alert(e.message || '上传失败')
  } finally {
    if (type === 'top') {
      topImgUploading.value = false
      topImgProgress.value = 0
    } else {
      replyImgUploading.value = false
      replyImgProgress.value = 0
    }
    input.value = ''
  }
}

// 图片预览
function openImagePreview(url: string) {
  previewImage.value = url
}

// 工具函数
function checkLogin(): boolean {
  if (!localStorage.getItem('token')) {
    alert('请先登录')
    return false
  }
  return true
}

function goToUserSpace(userId: string) {
  window.open(`/user-space/${userId}`, '_blank')
}

function formatTime(dateStr: string): string {
  if (!dateStr) return ''
  const date = new Date(dateStr)
  const now = new Date()
  const diff = now.getTime() - date.getTime()
  const minutes = Math.floor(diff / 60000)
  const hours = Math.floor(diff / 3600000)
  const days = Math.floor(diff / 86400000)
  if (minutes < 1) return '刚刚'
  if (minutes < 60) return `${minutes}分钟前`
  if (hours < 24) return `${hours}小时前`
  if (days < 30) return `${days}天前`
  return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`
}


function autoResize(e: Event) {
  const textarea = e.target as HTMLTextAreaElement
  textarea.style.height = 'auto'
  textarea.style.height = Math.min(textarea.scrollHeight, 150) + 'px'
}

watch(() => props.articleId, () => {
  if (props.articleId && !isMobile.value) fetchComments()
})
</script>

